function renderNewCheck(){
  const templates=[...templateSeed,...state.templates].filter(t=>t.items?.length);
  const draft=window.__newCheckDraft||{title:templates[0]?.name||'现场安全检查',site:'',owner:'林安',date:new Date().toLocaleDateString('en-CA'),templateId:templates[0]?.id||'',items:structuredClone(templates[0]?.items||[])};
  window.__newCheckDraft=draft;
  layout(`<div class="page-breadcrumb"><button class="text-action" id="back-new-check">← 返回现场检查</button><span>现场检查　/　新建任务</span></div><div class="new-check-heading"><div><h2>新建现场检查</h2></div><div class="new-check-actions"><button class="button" id="cancel-new-check">取消</button><button class="button primary" id="save-new-check">创建并开始检查</button></div></div><section class="new-check-layout"><div class="new-check-main"><section class="detail-card"><div class="section-title"><span>01</span><div><h3>任务信息</h3></div></div><div class="form-grid"><label class="field full"><span>检查名称</span><input id="new-title" value="${esc(draft.title)}"/></label><label class="field"><span>厂区与范围</span><input id="new-site" placeholder="填写厂区 / 车间 / 区域" value="${esc(draft.site)}"/></label><label class="field"><span>负责人</span><input id="new-owner" value="${esc(draft.owner)}"/></label><label class="field"><span>计划日期</span><input id="new-date" type="date" value="${esc(draft.date)}"/></label><label class="field"><span>检查模板</span><select id="new-template">${templates.map(t=>`<option value="${esc(t.id)}" ${selected(t.id,draft.templateId)}>${esc(t.name)} · ${t.items.length} 项</option>`).join('')}</select></label></div></section><section class="detail-card checklist-builder"><div class="section-title"><span>02</span><div><h3>检查项</h3></div><button class="button" id="add-new-item">＋ 添加检查项</button></div><div id="new-items-list"></div></section></div><aside class="new-check-side"><section class="detail-card"><h3>检查任务预览</h3><div class="preview-stat"><b id="new-items-count">${draft.items.length}</b><span>个检查项</span></div><div class="preview-line"><span>状态</span><b>待开始</b></div><div class="preview-line"><span>检查结果</span><b>现场逐项填写</b></div><div class="preview-note">不符合项可在现场记录中直接转为整改任务，并携带现场记录和图片证据。</div></section></aside></section>`);
  const list=document.querySelector('#new-items-list');
  const drawItems=()=>{list.innerHTML=draft.items.map((item,i)=>`<article class="new-item-editor"><div class="new-item-editor-head"><span>${String(i+1).padStart(2,'0')}</span><button class="text-action" data-remove-new-item="${i}">删除</button></div><div class="form-grid"><label class="field full"><span>检查项</span><input data-new-item="text" data-index="${i}" value="${esc(item.text||'')}" placeholder="例如：检查防护装置是否安装牢固"/></label><label class="field"><span>风险等级</span><select data-new-item="risk" data-index="${i}"><option ${selected('高',item.risk)}>高</option><option ${selected('中',item.risk||'中')}>中</option><option ${selected('低',item.risk)}>低</option></select></label><label class="field"><span>检查类别</span><input data-new-item="category" data-index="${i}" value="${esc(item.category||'现场安全')}"/></label><label class="field"><span>核查方法</span><textarea data-new-item="method" data-index="${i}" placeholder="描述现场如何核查">${esc(item.method||'')}</textarea></label><label class="field"><span>合格标准</span><textarea data-new-item="criteria" data-index="${i}" placeholder="描述什么情况判定为合格">${esc(item.criteria||'')}</textarea></label><label class="field full"><span>建议证据</span><input data-new-item="evidence" data-index="${i}" value="${esc(item.evidence||'')}" placeholder="现场照片、记录或检测报告"/></label></div></article>`).join('');document.querySelector('#new-items-count').textContent=draft.items.length;list.querySelectorAll('[data-new-item]').forEach(input=>input.oninput=input.onchange=()=>{draft.items[Number(input.dataset.index)][input.dataset.newItem]=input.value;});list.querySelectorAll('[data-remove-new-item]').forEach(button=>button.onclick=()=>{draft.items.splice(Number(button.dataset.removeNewItem),1);drawItems();});};
  document.querySelector('#new-template').onchange=()=>{draft.templateId=document.querySelector('#new-template').value;const selectedTemplate=templates.find(t=>t.id===draft.templateId);draft.items=structuredClone(selectedTemplate?.items||[]);drawItems();};document.querySelector('#add-new-item').onclick=()=>{draft.items.push({text:'',category:'现场安全',risk:'中',method:'',criteria:'',evidence:''});drawItems();};document.querySelectorAll('#new-title,#new-site,#new-owner,#new-date').forEach(input=>input.oninput=()=>{draft[{ 'new-title':'title','new-site':'site','new-owner':'owner','new-date':'date'}[input.id]]=input.value;});
  const close=()=>{window.__newCheckDraft=null;currentView='checks';render();};document.querySelector('#back-new-check').onclick=close;document.querySelector('#cancel-new-check').onclick=close;document.querySelector('#save-new-check').onclick=async()=>{const button=document.querySelector('#save-new-check');if(!draft.title.trim()||!draft.site.trim()||!draft.owner.trim()||!draft.date)return alert('请填写检查名称、范围、负责人和计划日期');if(!draft.items.length)return alert('请至少添加一个检查项');if(draft.items.some(item=>!String(item.text||'').trim()))return alert('请补充所有检查项内容');button.disabled=true;button.textContent='保存中…';const check={id:`CHK-${crypto.randomUUID()}`,title:draft.title.trim(),site:draft.site.trim(),owner:draft.owner.trim(),date:draft.date,status:'待开始',progress:'0%',items:draft.items.length,templateId:draft.templateId,checkItems:draft.items.map(item=>({...item,text:String(item.text).trim(),result:'待检查',note:'',evidenceNote:'',attachments:[]}))};try{const saved=await apiRequest('checks','POST',check);state.checks.unshift(saved);serverSnapshot.checks[saved.id]=structuredClone(saved);localStorage.setItem('ehs-loop-state',JSON.stringify(state));window.__newCheckDraft=null;currentView='checks';selectedCheckId=saved.id;render();}catch(error){button.disabled=false;button.textContent='创建并开始检查';alert('创建失败：'+error.message);}};drawItems();
}
function modal(title, form, submit) { const wrap=document.createElement('div'); wrap.className='modal-backdrop'; wrap.innerHTML=`<div class="modal"><div class="card-head"><h3>${title}</h3><button class="close" aria-label="关闭">×</button></div><div class="card-body">${form}<div class="modal-actions"><button class="button ghost cancel">取消</button><button class="button primary confirm">${submit}</button></div></div></div>`; document.body.appendChild(wrap); const close=()=>wrap.remove(); wrap.querySelector('.close').onclick=close; wrap.querySelector('.cancel').onclick=close; return {wrap,close}; }
function openCheckIssue(check,index){const item=check.checkItems[index];const m=modal('转为整改任务',`<div class="form-grid"><div class="field full"><label>问题描述</label><textarea id="convert-title">${esc(item.note||item.text)}</textarea></div><div class="field"><label>整改责任人 <span aria-hidden="true">*</span></label><input id="convert-owner" type="text" required placeholder="填写部门或姓名"/></div><div class="field"><label>整改期限 <span aria-hidden="true">*</span></label><input id="convert-deadline" type="date" required value="${new Date(Date.now()+7*86400000).toLocaleDateString('en-CA')}"/></div></div><p class="issue-editor-error" role="alert"></p>`,'创建整改任务');m.wrap.querySelector('.confirm').onclick=async()=>{const title=m.wrap.querySelector('#convert-title').value.trim(),owner=m.wrap.querySelector('#convert-owner').value.trim(),deadline=m.wrap.querySelector('#convert-deadline').value;if(!title||!owner||!deadline)return alert('请填写问题描述、整改责任人和期限');const button=m.wrap.querySelector('.confirm');button.disabled=true;try{clearTimeout(checkSaveTimer);await saveCheck(check);const response=await fetch(`/api/checks/${encodeURIComponent(check.id)}/items/${index}/issue`,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({title,owner,deadline})});const issue=await response.json();if(!response.ok)throw new Error(issue.error);if(!state.issues.some(i=>i.id===issue.id))state.issues.unshift(issue);item.issueId=issue.id;serverSnapshot.issues[issue.id]=structuredClone(issue);serverSnapshot.checks[check.id]=structuredClone(check);localStorage.setItem('ehs-loop-state',JSON.stringify(state));m.close();renderCheckDetail();}catch(error){button.disabled=false;m.wrap.querySelector('[role="alert"]').textContent=error.message;}};}

function openIssueModal(){const m=modal('登记整改问题',`<div class="form-grid"><div class="field full"><label>问题描述</label><textarea id="i-title" placeholder="例如：2号冲床防护罩存在松动"></textarea></div><div class="field"><label>风险等级</label><select id="i-risk"><option>高</option><option selected>中</option><option>低</option></select></div><div class="field"><label>问题类别</label><select id="i-category"><option>机械安全</option><option>用电安全</option><option>消防安全</option><option>环境管理</option></select></div><div class="field"><label>位置</label><input id="i-location" placeholder="车间 / 区域"/></div><div class="field"><label>责任人</label><input id="i-owner" placeholder="部门 · 姓名"/></div><div class="field"><label>整改期限</label><input id="i-date" type="date" value="2026-11-07"/></div></div>`,'登记问题');m.wrap.querySelector('.confirm').onclick=()=>{let title=m.wrap.querySelector('#i-title').value.trim();if(!title)return alert('请填写问题描述');state.issues.unshift({id:`R-${1029+state.issues.length}`,title,category:m.wrap.querySelector('#i-category').value,location:m.wrap.querySelector('#i-location').value||'待补充',risk:m.wrap.querySelector('#i-risk').value,owner:m.wrap.querySelector('#i-owner').value||'待分配',deadline:m.wrap.querySelector('#i-date').value,status:'待整改'});save();m.close();render();};}
